def bidualProductJoin (p : Bidual 𝕜 E × Bidual 𝕜 F) : Bidual 𝕜 (E × F) :=
  p.1.comp (transpose (ContinuousLinearMap.inl 𝕜 E F)) +
    p.2.comp (transpose (ContinuousLinearMap.inr 𝕜 E F))

